MATCH (p:Player)-[:ExtractedFrom]->(:Document)
WITH DISTINCT p
WHERE (
  (
    CAST(p.nba_championships AS INT64) > 2
    AND NOT EXISTS {
      MATCH (p)-[r:PlaysFor]->(t:Team)
      WHERE r.tenure = 'latest' AND t.team_name = 'Houston Rockets'
    }
  )
  OR EXISTS {
    MATCH (p)-[:PlaysFor]->(t:Team)
    WHERE CAST(t.founded_year AS INT64) <> 1949
      AND CAST(t.championships AS INT64) <> 1
  }
)
WITH p.position AS col1, SUM(CAST(p.mvp_awards AS INT64)) AS col2
RETURN col1 AS col1, col2 AS col2
